using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class TwoVoiceTests {
 static int count;static string root;static void Check(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}static void Reject(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception(name);}
 sealed class E:KokoroEngine {public int Calls,Disposals,Checks;public bool Fail;public short Value;public double Seconds;public List<string> Texts=new List<string>();public override void CheckFiles(){Checks++;}public override Wave Generate(string t,double speed,string output){Calls++;Texts.Add(t);if(Fail)throw new Exception("fixture B speech failure");return new Wave{Rate=24000,Samples=Enumerable.Repeat(Value,(int)(Seconds*24000/speed)).ToArray()};}public override void Dispose(){Disposals++;base.Dispose();}}
 static E Engine(string name,short value,double seconds){return new E{Root=root,VoiceName=name,Value=value,Seconds=seconds,DeviceMode="cpu"};}
 static List<Cue> Srt(){return Scripts.ParseSrt("1\n00:00:00,200 --> 00:00:02,200\n[A] Alpha sentence.\n\n2\n00:00:02,500 --> 00:00:04,500\n[B] Beta sentence.\n\n3\n00:00:04,500 --> 00:00:06,500\n[B] Another beta.\n\n4\n00:00:06,500 --> 00:00:08,500\n[A] Last alpha.\n");}
 static RenderOptions Opt(string name,bool prose=false){return new RenderOptions{TwoVoices=true,VoiceAKey="test:A",VoiceBKey="test:B",VoiceAInfo="alpha profile",VoiceBInfo="beta profile",Prose=prose,Locked=!prose,SlowShort=false,Breathing=BreathMode.None,Gap=.15,ReportContext=new VoiceReportContext{SourcePath=Path.Combine(root,name+(prose?".txt":".srt"))}};}
 public static void Main(){root=Path.Combine(Path.GetTempPath(),"V15 hai giọng "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var c=Srt();Check(c.Select(x=>x.Speaker).SequenceEqual(new[]{"A","B","B","A"})&&c[0].Words==2&&!c.Any(x=>x.Text.Contains("[")),"SRT labels are separate from speech and word count");Check(Scripts.ParseSrt(Scripts.ToSrt(c)).Select(x=>x.Speaker).SequenceEqual(c.Select(x=>x.Speaker)),"Tagged SRT round trip preserves assignments and timeline");
  foreach(string bad in new[]{"[a] lower.","[C] unknown.","[A]", "[A] First [B] second.","A: wrong.","[ B ] wrong."})Reject(()=>Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:02,000\n"+bad),"Reject malformed / mixed speaker syntax "+bad);
  Reject(()=>Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:02,000\n[A] First.\n\n2\n00:00:02,000 --> 00:00:04,000\nMissing label."),"Reject partly labelled SRT before synthesis");
  var txt=LongText.Parse("[A] First alpha. Second alpha.\n[B] First beta!\n[B] More beta.\n[A] Last alpha.");Check(txt.Count==5&&txt.Select(x=>x.Speaker).SequenceEqual(new[]{"A","A","B","B","A"})&&txt.All(x=>x.Prose),"TXT splits sentences while keeping the turn's speaker");Reject(()=>LongText.Parse("[A] First.\nMissing tag."),"TXT mixed labelled and unlabelled turns fail");
  var wrapped=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:02,000\n[A] First line\nsecond line.\n");Check(wrapped[0].Text=="First line second line."&&wrapped[0].Speaker=="A","Multiline SRT retains one label per cue");
  Check(VoiceRenderReport.Snapshot(c).Select(x=>x.Speaker).SequenceEqual(c.Select(x=>x.Speaker)),"Report snapshot preserves speaker assignments");var settings=new VoiceSettings{TwoVoices=true,VoiceBKey="U:private-clone",Key="C:adam_rvc"};var restored=VoiceSettings.From(settings.Xml());Check(restored.TwoVoices&&restored.VoiceBKey=="U:private-clone"&&restored.Key=="C:adam_rvc","Session/preset persists A and B independently");Check(!VoiceSettings.From(new System.Xml.Linq.XElement("settings")).TwoVoices,"Older sessions default to one voice");
  var stages=AnchoredVoice.Plan(c);Check(stages.Count==3&&stages.All(s=>s.Cues.Select(SpeakerScript.Role).Distinct().Count()==1),"V15.6 stage boundaries protect every speaker switch without forcing alternation");var join=c.Select(x=>new Cue{Id=x.Id,Start=x.Start,End=x.End,Text="unfinished",Speaker=x.Speaker}).ToList();var joined=SpeechGroups.Join(join);Check(joined.Count==3&&joined.Select(x=>x.Speaker).SequenceEqual(new[]{"A","B","A"}),"Flexible sentence joining never merges across voices");
  var a=Engine("Alpha voice",1500,.6);var b=Engine("Beta voice",3000,1);var o=Opt("locked");File.WriteAllText(o.ReportContext.SourcePath,Scripts.ToSrt(c));string sourceHash=StateFiles.Hash(o.ReportContext.SourcePath);string path;using(var router=new TwoVoiceEngine(a,b,"test:A","test:B",c)){path=Renderer.Render(c,router,o,OutputFiles.Beside(o.ReportContext.SourcePath),(p,m)=>{});var w=Wave.Read(path);Check(FinalAudio.PcmFrames(path)==204000&&w.Samples[12000]==1500&&w.Samples[72000]==3000&&w.Samples[120000]==3000&&w.Samples[168000]==1500,"Locked SRT produces one exact-length WAV with A-B-B-A audio in correct windows");Check(w.Samples[0]==0&&w.Samples[55000]==0,"Source leading silence and valid gaps remain intact");Check(a.Calls==2&&b.Calls==2&&a.Texts.All(t=>!t.Contains("["))&&b.Texts.All(t=>!t.Contains("[")),"Only spoken text reaches the assigned engine");Check(o.RunReport.Units.Select(u=>u.Voice).SequenceEqual(new[]{"Alpha voice","Beta voice","Beta voice","Alpha voice"})&&o.RunReport.Units.Select(u=>u.VoiceKey).SequenceEqual(new[]{"test:A","test:B","test:B","test:A"}),"Per-cue report records actual voice identity and key");Check(StateFiles.Hash(o.ReportContext.SourcePath)==sourceHash&&File.ReadAllText(o.RunReport.PathName).Contains("HAI GIỌNG"),"Source untouched; adjacent report includes two-voice map");}
  Check(a.Disposals==1&&b.Disposals==1,"Render owns and releases both voice engines");
  a=Engine("Alpha voice",1500,.6);b=Engine("Beta voice",3000,1);c=Srt();o=Opt("cache-first");using(var router=new TwoVoiceEngine(a,b,"test:A","test:B",c)){router.PreviewCache=new SpeechCache();Renderer.Render(c,router,o,path,(p,m)=>{});o=Opt("cache-second");string next=Renderer.Render(Srt(),router,o,path,(p,m)=>{});Check(a.Calls==2&&b.Calls==2&&o.RunReport.Units.All(u=>u.CacheCalls==1),"Repeated render reuses distinct per-voice audio cache");Check(next!=path&&File.Exists(path),"Second WAV preserves prior successful output");}
  a=Engine("Alpha voice",1500,.6);b=Engine("Beta voice",3000,1);o=Opt("natural",true);using(var router=new TwoVoiceEngine(a,b,"test:A","test:B",txt)){string file=Renderer.Render(txt,router,o,Path.Combine(root,"natural.wav"),(p,m)=>{});var w=Wave.Read(file);Check(txt[2].Start>txt[1].End&&w.Samples[(int)((txt[2].Start+.1)*24000)]==3000&&w.Samples[(int)((txt[4].Start+.1)*24000)]==1500,"Natural TXT concatenates actual durations and speaker turns into one WAV");Check(o.RunReport.Units.All(u=>u.Before.HasValue&&u.After.HasValue),"Natural TXT report measures each speaker's actual duration");}
  c=Srt();a=Engine("Alpha voice",1500,.6);b=Engine("Beta voice",3000,1);b.Fail=true;o=Opt("failure");using(var router=new TwoVoiceEngine(a,b,"test:A","test:B",c)){Reject(()=>Renderer.Render(c,router,o,Path.Combine(root,"failure.wav"),(p,m)=>{}),"B engine failure aborts whole render");Check(!File.Exists(Path.Combine(root,"failure.wav"))&&o.RunReport.Outcome=="THẤT BẠI"&&o.RunReport.Current.Voice=="Beta voice"&&File.ReadAllText(o.RunReport.PathName).Contains("fixture B speech failure"),"Failure report identifies B and no partial final WAV is published");}
  c=Srt();a=Engine("Alpha voice",1500,.6);b=Engine("Beta voice",3000,1);o=Opt("cancel");using(var router=new TwoVoiceEngine(a,b,"test:A","test:B",c)){Reject(()=>Renderer.Render(c,router,o,Path.Combine(root,"cancel.wav"),(p,m)=>{if(p>0)router.Cancel();}),"Stop cancels mixed render");Check(a.Cancelled&&b.Cancelled&&o.RunReport.Outcome=="ĐÃ DỪNG"&&!File.Exists(Path.Combine(root,"cancel.wav")),"Cancellation reaches both engines and leaves no published WAV");}
  c=Srt();o=Opt("disabled");o.TwoVoices=false;a=Engine("Alpha voice",1500,.6);Reject(()=>Renderer.Render(c,a,o,Path.Combine(root,"disabled.wav"),(p,m)=>{}),"One-voice mode refuses to silently render B as A");Check(a.Calls==0&&File.Exists(o.RunReport.PathName),"Mode error is reported before synthesizing");
  c=Srt();a=Engine("Alpha",1500,.6);b=Engine("Beta",3000,1);a.Kind=b.Kind=EngineKind.Chatterbox;using(var router=new TwoVoiceEngine(a,b,"a","b",c)){router.SelectSpeaker("A");router.SelectSpeaker("A");router.SelectSpeaker("B");Check(a.Disposals==1&&b.Disposals==0,"Switch releases previous heavyweight model; same-speaker continuation keeps it");}
  string file1=Path.Combine(root,"queue1.srt"),file2=Path.Combine(root,"queue2.txt");File.WriteAllText(file1,Scripts.ToSrt(Srt()));File.WriteAllText(file2,"[A] Text alpha.\n[B] Text beta.");var jobs=new List<BatchJob>{BatchJob.Load(file1),BatchJob.Load(file2)};string queue=Path.Combine(root,"queue.xml");QueueStore.Save(queue,jobs);jobs=QueueStore.Load(queue);Check(jobs[0].Cues[1].Speaker=="B"&&jobs[1].Cues[1].Speaker=="B","Saved/reopened queue preserves SRT and TXT speaker roles");a=Engine("Queue alpha",1500,.6);b=Engine("Queue beta",3000,1);using(var router=new TwoVoiceEngine(a,b,"qa","qb",jobs.SelectMany(j=>j.Cues))){BatchRunner.Run(jobs,false,()=>router.Cancelled,(j,output,notify)=>{var options=Opt(j.Name,!j.Timed);options.ReportContext.SourcePath=j.InputPath;return Renderer.Render(j.Cues,router,options,output,notify);},(p,m)=>{});}Check(jobs.All(j=>j.State==JobState.Done&&File.Exists(j.OutputPath))&&b.Calls==3,"Batch processes both input types with shared A/B mapping");
  c=Srt();a=Engine("Anchor alpha",1500,2);b=Engine("Anchor beta",3000,2);o=Opt("anchored");o.Anchored=true;using(var router=new TwoVoiceEngine(a,b,"aa","bb",c)){string wav=Renderer.Render(c,router,o,Path.Combine(root,"anchored.wav"),(p,m)=>{});Check(o.AnchorResult.Complete&&o.AnchorResult.Stages.Count==3&&FinalAudio.PcmFrames(wav)==204000,"Two-voice V15.6 runs real FFmpeg fitting and preserves total source duration");Check(o.RunReport.Units.Select(u=>u.Speaker).SequenceEqual(new[]{"A","B","B","A"})&&o.RunReport.Units.All(u=>!u.After.HasValue&&!u.Start.HasValue),"V15.6 reports actual speaker and does not invent final per-cue measurements");}
  txt=LongText.Parse("[A] First alpha.\n[B] First beta.");a=Engine("Target alpha",1500,2);b=Engine("Target beta",3000,3);o=Opt("dual-target",true);o.TargetSeconds=5.15;o.NormalizeLoudness=true;using(var router=new TwoVoiceEngine(a,b,"ta","tb",txt)){string wav=Renderer.Render(txt,router,o,Path.Combine(root,"dual-target.wav"),(p,m)=>{});Check(o.TargetResult.Complete&&FinalAudio.PcmFrames(wav)==123600,"Two-voice TXT duration target and loudness normalization produce exact final frames");Check(o.RunReport.Units[1].Voice=="Target beta"&&o.RunReport.Units.All(u=>!u.Start.HasValue&&u.OriginalStart.HasValue),"Whole-TXT fitting preserves voice map while keeping final cue timing unknown");}
  var meter=new ReadingMeter(LongText.Parse("[A] One two three four.\n[B] One two three four."),1);var measured=new Cue{Speaker="A",Text="One two three four.",Actual=8};var reading=meter.Update(measured,8,"");Check(reading.EstimateLow<10&&reading.EstimateHigh<12,"TXT estimation does not transfer measured slow A rate to unmeasured B");
  Console.WriteLine("TOTAL TWO VOICE "+count+" passed. Fixtures: "+root);
 }
}
